const fs = require('fs'), path = require('path'), os = require('os'); const c = fs.constants;
const d = fs.mkdtempSync(path.join(os.tmpdir(), 'm41-')); const f = path.join(d, 'f'); fs.writeFileSync(f, 'abc'); fs.symlinkSync(f, path.join(d, 'l'));
const T = (l, fn) => { try { const r = fn(); console.log(l, 'ok', r === undefined ? '' : r); } catch (e) { console.log(l, e.code, e.syscall); } };
T('O_DIRECTORY on file', () => { fs.closeSync(fs.openSync(f, c.O_RDONLY | c.O_DIRECTORY)); });
T('O_DIRECTORY on dir', () => { fs.closeSync(fs.openSync(d, c.O_RDONLY | c.O_DIRECTORY)); });
T('O_NOFOLLOW on link', () => { fs.closeSync(fs.openSync(path.join(d, 'l'), c.O_RDONLY | c.O_NOFOLLOW)); });
T('O_NOFOLLOW on file', () => { fs.closeSync(fs.openSync(f, c.O_RDONLY | c.O_NOFOLLOW)); });
T('O_APPEND pos 0', () => { const fd = fs.openSync(f, c.O_WRONLY | c.O_APPEND); fs.writeSync(fd, 'X', 0); fs.writeSync(fd, Buffer.from('Y'), 0, 1, 0); fs.closeSync(fd); return fs.readFileSync(f, 'utf8'); });
T('O_CREAT|O_EXCL exists', () => { fs.openSync(f, c.O_CREAT | c.O_EXCL | c.O_WRONLY); });
T('O_TRUNC', () => { fs.closeSync(fs.openSync(f, c.O_WRONLY | c.O_TRUNC)); return fs.statSync(f).size; });
T('flag string ax', () => { fs.writeFileSync(f, 'q', { flag: 'ax' }); });
T('O_SYNC|O_DSYNC write', () => { const fd = fs.openSync(f, c.O_WRONLY | c.O_SYNC | c.O_DSYNC); fs.writeSync(fd, 'sync'); fs.closeSync(fd); return fs.readFileSync(f, 'utf8'); });
T('S_ bits', () => [c.S_IRUSR, c.S_IWUSR, c.S_IXUSR, c.S_IRWXG, c.S_IRWXO, c.S_IFBLK, c.S_IFCHR, c.S_IFIFO, c.S_IFSOCK].join(','));
T('UV', () => [c.UV_DIRENT_FILE, c.UV_FS_COPYFILE_EXCL, c.COPYFILE_FICLONE, c.UV_FS_SYMLINK_DIR].join(','));
T('keys', () => Object.keys(c).length);
T('mode check', () => (fs.statSync(f).mode & c.S_IRUSR) !== 0);
fs.rmSync(d, { recursive: true });
